INSERT INTO "statutory_rule_sets" ("statute", "jurisdiction", "version", "valid_from", "valid_to", "values", "source", "verify", "status", "law_version", "published_at") VALUES ('IN.PT', 'IN-OD', '2026-v1', '2026-04-01', NULL, '{"kind":"pt","basis":"monthly","annualCap":"0","slabs":[]}', 'Odisha repealed its professional tax from 1 Apr 2026 (Odisha Ordinance 02 of 2026, promulgated 21 Apr 2026); dues to March 2026 stay payable (that schedule is not loaded, question 2381). Secondary only: https://www.scconline.com/blog/post/2026/04/23/odisha-repeals-levy-of-professional-tax-effective-from-1-april-2026/ . TODO: CA checklist item 20 (was the ordinance replaced by an Act).', true, 'published', 'OLD-ACT', CURRENT_TIMESTAMP);
